<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>}>()
const config=ref<Record<string,any>>({enabled:false,version:0,chat_id:'',bot_token:'',command_polling:false,allowed_user_ids:[],commands:['status','help'],events:[],report_minutes:60,report_sections:['status','traffic'],quota_percent:80})
const ids=ref(''),logs=ref<Record<string,any>[]>([]),status=ref<Record<string,any>>({}),busy=ref(false),error=ref(''),notice=ref(''),unbinding=ref(false)
const commands=[{id:'status',name:'状态概览'},{id:'hosts',name:'主机列表'},{id:'traffic',name:'用量汇总'},{id:'users',name:'用户额度'},{id:'help',name:'帮助'}]
const events=[{id:'host_offline',name:'主机离线'},{id:'host_online',name:'主机恢复'},{id:'quota',name:'用户额度阈值'},{id:'certificate',name:'证书不足 14 天'}]
async function load(){status.value=await props.api('notifications/telegram');config.value={...config.value,...status.value.config,bot_token:''};ids.value=(config.value.allowed_user_ids??[]).join('\n');logs.value=await props.api('notifications/log')}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
function save(){void run(async()=>{const allowed=ids.value.split(/[\s,]+/).filter(Boolean).map(Number);if(allowed.some(v=>!Number.isSafeInteger(v)||v<1))throw Error('允许用户 ID 必须是正整数');await props.api('notifications/telegram','PUT',{...config.value,allowed_user_ids:allowed});await load();notice.value='已保存。只会向指定聊天发送选中的通知；关闭绑定后停止后续轮询与发送。'})}
function test(preview:boolean){void run(async()=>{const r=await props.api('notifications/telegram/test','POST',{preview});notice.value=(preview?'仅预览，未发送：':'已发送测试通知：')+'\n'+r.message;logs.value=await props.api('notifications/log')})}
function unbind(){void run(async()=>{await props.api('notifications/telegram','DELETE');unbinding.value=false;config.value={...config.value,enabled:false,token_configured:false,version:0,bot_token:''};await load();notice.value='已解绑并删除本平台保存的机器人令牌；Telegram 端机器人仍保留。'})}
onMounted(()=>void run(load));onUnmounted(()=>config.value.bot_token='')
</script>
<template><section class="panel publish-card notification-panel"><span class="eyebrow">NOTIFICATIONS / TELEGRAM</span><h2>通知与机器人查询</h2><p class="muted">使用 Telegram 官方 Bot API 主动连接，不需要开放 Webhook 端口。同一机器人请只由本平台长轮询；已有 Webhook 或其他轮询程序会冲突。本平台不会自动删除其他 Webhook。</p>
<p v-if="error" class="error" role="alert">{{error}}</p><pre v-if="notice" class="notice notification-message" role="status">{{notice}}</pre>
<form @submit.prevent="save"><div class="fields"><label>机器人 Token<input v-model="config.bot_token" type="password" autocomplete="off" :placeholder="config.token_configured?'已加密保存；留空保留':'从 BotFather 创建机器人后填写'" :required="!config.token_configured"></label><label>通知聊天 ID<input v-model="config.chat_id" required placeholder="个人 ID 或负数群组 ID" inputmode="numeric"></label></div>
<p class="form-note">先在 Telegram 与机器人开始聊天，或将其加入通知群。Token 只写入加密存储，不回显、不写日志；不要将它发到公开聊天。报告可能包含主机名、用户名称与用量，启用即授权发送到上述聊天。</p>
<label class="check-label"><input v-model="config.enabled" type="checkbox">启用此通知绑定</label>
<h3>定时报告</h3><div class="fields"><label>发送间隔（分钟；0 关闭）<input v-model.number="config.report_minutes" type="number" min="0" max="10080"></label><label>用户流量提醒阈值 %<input v-model.number="config.quota_percent" type="number" min="1" max="100"></label></div><p class="muted">最短 15 分钟。停机期间跳过过期轮次，恢复后发送一份报告；不会补发大量历史通知。</p>
<fieldset class="choice-list"><legend>定时报告内容</legend><label v-for="c in commands.filter(c=>c.id!=='help')" :key="c.id"><input v-model="config.report_sections" type="checkbox" :value="c.id">{{c.name}}</label></fieldset>
<fieldset class="choice-list"><legend>事件提醒</legend><label v-for="e in events" :key="e.id"><input v-model="config.events" type="checkbox" :value="e.id">{{e.name}}</label></fieldset>
<h3>只读命令</h3><label class="check-label"><input v-model="config.command_polling" type="checkbox">长轮询接收查询命令</label><label>允许执行查询的 Telegram 用户 ID（每行一个）<textarea v-model="ids" rows="3" placeholder="必须显式授权；群内其他成员不能查询"></textarea></label><fieldset class="choice-list"><legend>允许命令</legend><label v-for="c in commands" :key="c.id"><input v-model="config.commands" type="checkbox" :value="c.id">/{{c.id}} · {{c.name}}</label></fieldset><p class="form-note">同时匹配聊天和用户 ID；只接受最近 2 分钟的消息，每轮最多回复 3 条。命令不提供 Shell、启停、删除、凭据或订阅链接操作。</p>
<div class="notification-actions"><button class="primary" :disabled="busy">保存通知设置</button><button class="secondary" type="button" :disabled="busy||!config.token_configured" @click="test(true)">预览通知</button><button class="secondary" type="button" :disabled="busy||!config.token_configured||!config.enabled" @click="test(false)">向已绑定聊天发送测试</button><button v-if="config.token_configured" class="text-button danger" type="button" :disabled="busy" @click="unbinding=true">解绑机器人</button></div></form>
<p class="muted">最近轮询：{{status.last_poll_at||'未运行'}} · 最近发送：{{status.last_send_at||'暂无'}}。事件每分钟检查；同一状态只提醒一次，网络重试可能重复投递。</p><p v-if="status.last_error" class="error">{{status.last_error}}</p>
<details><summary>最近通知记录（最多 100 条）</summary><div class="table-scroll"><table><thead><tr><th>时间</th><th>事件</th><th>结果</th></tr></thead><tbody><tr v-for="l in logs" :key="l.id"><td>{{new Date(l.created_at).toLocaleString()}}</td><td>{{l.event}}</td><td>{{l.state}} {{l.detail}}</td></tr></tbody></table></div></details>
<div v-if="unbinding" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="解绑机器人"><div class="form-content"><h2>解绑 Telegram？</h2><p>删除本平台保存的 Token 并停止后续轮询、提醒和定时报告。不会删除 Telegram 端机器人或聊天。</p></div><div class="modal-footer"><button class="secondary" @click="unbinding=false">取消</button><button class="primary" :disabled="busy" @click="unbind">确认解绑</button></div></section></div>
</section></template>
<style scoped>.notification-panel h3{margin:28px 0 14px}.notification-panel fieldset{margin:18px 0;padding:14px;border:1px solid var(--border);border-radius:12px}.notification-actions{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.notification-message{white-space:pre-wrap;font-family:inherit}.notification-panel input{max-width:100%}@media(max-width:600px){.notification-actions button{flex:1;min-width:45%}}</style>
